    "Error getting Aloha Social notifications" : "Virhe Aloha Social -ilmoitusten haussa",
    "No Aloha Social notifications!" : "Ei Aloha Social -ilmoituksia!",
    "Failed to get Aloha Social notifications" : "Aloha Social -ilmoitusten haku epäonnistui",
    "Go to Aloha Social app" : "Siirry Aloha Social -sovellukseen",
    "_One account could not be reached from this server:_::_%n accounts could not be reached from this server:_" : ["Yhtä tiliä ei tavoitettu tältä palvelimelta:","%n tiliä ei tavoitettu tältä palvelimelta:"],
    "Add some with the starter_packs app setting, or read them in from other servers with starter_pack_sources." : "Lisää niitä sovellusasetuksella starter_packs tai lue niitä muilta palvelimilta asetuksella starter_pack_sources.",
